// Merge conversation and negotiation state
const trigger = $('Execute Workflow Trigger').item.json;
const conversation = $('Load Conversation').first()?.json || {};
const negotiation = $('Load Negotiation State').first()?.json || null;

const negData = trigger.negotiation_data || {};

// Determine negotiation status
let negStatus = negotiation?.negotiation_status || 'initial_contact';
let round = negotiation?.negotiation_round || 0;

// Update status based on message content
if (negData.is_acceptance) {
  negStatus = 'agreed';
} else if (negData.is_counter_offer) {
  negStatus = 'counter_offer';
  round++;
} else if (negData.is_offer) {
  negStatus = round === 0 ? 'first_offer' : 'negotiating';
  round++;
} else if (negData.is_inquiry_response) {
  negStatus = 'price_inquiry';
}

// Track best price
const detectedPrice = negData.detected_prices?.[0] || negData.price_from_meta;
let bestOffer = negotiation?.best_offer;
if (detectedPrice) {
  if (!bestOffer || detectedPrice < bestOffer) {
    bestOffer = detectedPrice;
  }
}

// Build price history entry
let priceHistory = negotiation?.price_history || [];
if (detectedPrice) {
  priceHistory.push({
    price: detectedPrice,
    round: round,
    direction: 'seller',
    timestamp: new Date().toISOString()
  });
}

return {
  json: {
    ...trigger,
    conversation_exists: !!conversation.conversation_id,
    current_stage: conversation.stage || 'new',
    message_count: conversation.message_count || 0,
    conversation_history: conversation.history || [],
    negotiation_exists: !!negotiation,
    negotiation_status: negStatus,
    negotiation_round: round,
    initial_price: negotiation?.initial_price || detectedPrice,
    target_price: negotiation?.target_price,
    current_offer: detectedPrice || negotiation?.current_offer,
    best_offer: bestOffer,
    price_history: priceHistory,
    moq: negData.moq_from_meta || negotiation?.moq,
    quantity: negData.detected_quantities?.[0] || negotiation?.quantity,
    detected_incoterm: negData.detected_incoterm || negotiation?.incoterm,
    max_rounds: negotiation?.max_rounds || 5
  }
};

// Determine negotiation strategy and build context for AI
const input = $input.item.json;

// Calculate negotiation leverage
const round = input.negotiation_round;
const maxRounds = input.max_rounds;
const initialPrice = input.initial_price;
const targetPrice = input.target_price;
const currentOffer = input.current_offer;
const bestOffer = input.best_offer;

// Strategy determination
let strategy = 'standard';
let aggressiveness = 0.5; // 0 = very soft, 1 = very aggressive
let targetDiscount = 0.15; // Default: aim for 15% discount

if (round === 0) {
  strategy = 'initial_inquiry';
  aggressiveness = 0.3;
} else if (round === 1) {
  strategy = 'first_counter';
  aggressiveness = 0.7;
  targetDiscount = 0.25; // Ask for more at first
} else if (round >= 2 && round < maxRounds - 1) {
  strategy = 'negotiate';
  aggressiveness = 0.5;
  targetDiscount = 0.18;
} else if (round >= maxRounds - 1) {
  strategy = 'final_push';
  aggressiveness = 0.4;
  targetDiscount = 0.12;
}

// If we have a target price, calculate needed discount
let suggestedCounterPrice = null;
if (currentOffer && targetPrice) {
  // If current offer is already at or below target, accept
  if (currentOffer <= targetPrice) {
    strategy = 'accept';
  } else {
    // Counter between target and current, moving up each round
    const progress = Math.min(round / maxRounds, 0.8);
    suggestedCounterPrice = targetPrice + (currentOffer - targetPrice) * progress * 0.3;
  }
} else if (currentOffer) {
  // No target price set - use standard discount target
  suggestedCounterPrice = currentOffer * (1 - targetDiscount);
}

// Build negotiation context summary
let priceHistorySummary = '';
if (input.price_history && input.price_history.length > 0) {
  priceHistorySummary = input.price_history
    .map(p => `Round ${p.round}: ${p.direction} proposed ${p.price}`)
    .join('\n');
}

return {
  json: {
    ...input,
    strategy: strategy,
    aggressiveness: aggressiveness,
    target_discount_pct: targetDiscount * 100,
    suggested_counter_price: suggestedCounterPrice ? Math.round(suggestedCounterPrice * 100) / 100 : null,
    price_history_summary: priceHistorySummary,
    should_accept: strategy === 'accept',
    is_stalled: round >= maxRounds
  }
};

