// Prepare acceptance response
const input = $input.item.json;

const acceptMessage = `Thank you for your offer! We're happy to accept the price of $${input.current_offer} per ${input.unit || 'unit'}. ` +
  `Could you please confirm the following details:\n` +
  `- Quantity: ${input.quantity || 'to be confirmed'}\n` +
  `- Shipping: ${input.detected_incoterm || 'to be discussed'}\n` +
  `- Payment terms: to be confirmed\n` +
  `- Lead time: to be confirmed\n\n` +
  `Please send us a proforma invoice so we can proceed. Looking forward to a successful partnership!`;

return {
  json: {
    reply_text: acceptMessage,
    action: 'send',
    handoff: false,
    stage: 'agreed',
    intent: 'negotiation_accept',
    negotiation_status: 'agreed',
    source: input.source,
    conversation_id: input.conversation_id,
    sender_id: input.sender_id,
    message_id: input.message_id,
    negotiation_round: input.negotiation_round,
    final_price: input.current_offer,
    price_history: input.price_history
  }
};

// Prepare handoff - negotiation stalled
const input = $input.item.json;

const handoffMessage = `Thank you for your patience. Let me check with my team on this and get back to you shortly.`;

return {
  json: {
    reply_text: handoffMessage,
    action: 'handoff',
    handoff: true,
    handoff_reason: 'negotiation_stalled_max_rounds',
    stage: 'negotiating',
    intent: 'negotiation_stalled',
    negotiation_status: 'stalled',
    source: input.source,
    conversation_id: input.conversation_id,
    sender_id: input.sender_id,
    message_id: input.message_id,
    negotiation_round: input.negotiation_round,
    best_offer: input.best_offer,
    price_history: input.price_history
  }
};

// Prepare negotiation reply
const input = $input.item.json;
const replyText = $('Generate Negotiation Reply').item.json.message.content;

// Update price history with our counter
let priceHistory = input.price_history || [];
if (input.suggested_counter_price) {
  priceHistory.push({
    price: input.suggested_counter_price,
    round: input.negotiation_round,
    direction: 'buyer',
    timestamp: new Date().toISOString()
  });
}

return {
  json: {
    reply_text: replyText,
    action: 'send',
    handoff: false,
    stage: 'negotiating',
    intent: 'negotiation_counter',
    negotiation_status: input.negotiation_status,
    source: input.source,
    conversation_id: input.conversation_id,
    sender_id: input.sender_id,
    message_id: input.message_id,
    negotiation_round: input.negotiation_round,
    suggested_counter_price: input.suggested_counter_price,
    best_offer: input.best_offer,
    price_history: priceHistory
  }
};
